-- 0006 — foreign keys for the platform tables (S5, 2026-10-15).
-- Generated by drizzle-kit from the schema's foreignKey() declarations, then
-- hand-edited: every constraint is added NOT VALID (drizzle-kit has no option
-- for it). Edit only before the first apply — the migrator never re-hashes
-- applied files.
--
-- Why NOT VALID: production holds ETL'd Era 1/2 rows that may reference parents
-- that never existed. NOT VALID skips the scan of existing rows, so this
-- migration does not fail on historical orphans and each ADD is quick. From the
-- moment it commits, every INSERT is checked, and so is every UPDATE that
-- changes an FK column. Updates to other columns of a historical orphan
-- (counters, feed_score, status) are not re-checked and keep working.
--
-- Locks: each ADD takes SHARE ROW EXCLUSIVE on the child and the parent table,
-- and the migrator runs every pending migration in ONE transaction, so those
-- locks are held until that transaction commits — together with whatever the
-- other pending migrations took (0004's ADD COLUMN holds ACCESS EXCLUSIVE on
-- users). Writers queue behind it meanwhile, and the ALTER itself queues behind
-- any open write transaction. A lock-order deadlock with an in-flight write
-- (e.g. createComment, which touches posts and comments while this holds posts
-- and wants comments) makes Postgres abort one side; if the migration loses,
-- the whole transaction rolls back cleanly (0004–0006 alike) and can be re-run.
--
-- Operator practice: migrate in a quiet window with the agent round stopped
-- (`launchctl unload ~/Library/LaunchAgents/com.swil.round.plist`), and bound
-- the lock wait. The migrator accepts no SET of its own; pass it as a startup
-- option, which node-postgres reads from PGOPTIONS (direct/unpooled URL):
--   PGOPTIONS='-c lock_timeout=5s' DATABASE_URL=<unpooled> npm --prefix server run db:migrate
-- A lock_timeout error rolls everything back; re-run when traffic is quiet.
--
-- Parents are tombstoned (status / deleted_at), never hard-deleted, so every
-- constraint is ON DELETE NO ACTION.
--
-- Not covered on purpose: lab/analytics tables (history that outlives any
-- account operation), polymorphic columns (likes.target_id), arrays, and
-- notifications.post_id / comment_id / message_id / conversation_id (a delivery
-- log that may name a soft-deleted target).
--
-- Validation is a later, owner-run step against the target database:
--   npm --prefix server run db:orphans            # read-only; exit 1 if any orphan
--   npm --prefix server run db:validate-fks -- --yes   # VALIDATE CONSTRAINT each
--
-- Rollback (one statement per constraint):
--   ALTER TABLE "api_keys" DROP CONSTRAINT "api_keys_user_id_fkey";
--   ALTER TABLE "bookmarks" DROP CONSTRAINT "bookmarks_user_id_fkey";
--   ALTER TABLE "bookmarks" DROP CONSTRAINT "bookmarks_post_id_fkey";
--   ALTER TABLE "comments" DROP CONSTRAINT "comments_post_id_fkey";
--   ALTER TABLE "comments" DROP CONSTRAINT "comments_author_id_fkey";
--   ALTER TABLE "comments" DROP CONSTRAINT "comments_parent_id_fkey";
--   ALTER TABLE "follows" DROP CONSTRAINT "follows_follower_id_fkey";
--   ALTER TABLE "follows" DROP CONSTRAINT "follows_following_id_fkey";
--   ALTER TABLE "likes" DROP CONSTRAINT "likes_user_id_fkey";
--   ALTER TABLE "posts" DROP CONSTRAINT "posts_author_id_fkey";
--   ALTER TABLE "posts" DROP CONSTRAINT "posts_board_id_fkey";
--   ALTER TABLE "posts" DROP CONSTRAINT "posts_echo_of_fkey";
--   ALTER TABLE "users" DROP CONSTRAINT "users_owner_id_fkey";
--   ALTER TABLE "messages" DROP CONSTRAINT "messages_conversation_id_fkey";
--   ALTER TABLE "messages" DROP CONSTRAINT "messages_sender_id_fkey";
--   ALTER TABLE "notifications" DROP CONSTRAINT "notifications_recipient_id_fkey";
--   ALTER TABLE "notifications" DROP CONSTRAINT "notifications_actor_id_fkey";

ALTER TABLE "api_keys" ADD CONSTRAINT "api_keys_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "public"."users"("id") ON DELETE no action ON UPDATE no action NOT VALID;--> statement-breakpoint
